#include "luma_platform.h"
#include "app.h"          // generated by slint-compiler

int main()
{
    auto platform = std::make_unique<LumaPlatform>();
    LumaPlatform* p = platform.get();
    if (!p->connect()) { printf("[slint-client] cannot connect to wayland\n"); return 1; }
    slint::platform::set_platform(std::move(platform));

    auto ui = AppWindow::create();
    ui->show();           // creates the window adapter -> xdg_toplevel
    ui->run();            // Platform::run_event_loop()
    return 0;
}